oxy_webhelp_navlinks = {"arch_manage_azure_arch_loc-d39536e8421":{"topics":[{"title":"Connecting a reader to an archival location manually","shortdesc":"<p class=\"shortdesc\">Connect a Rubrik cluster to an archival location as a reader Rubrik cluster for         disaster recovery.<\/p>","href":"archival\/arch_connecting_reader_arch_loc.html","attributes":{"data-id":"arch_connecting_reader_arch_loc"},"menu":{"hasChildren":false},"tocID":"arch_connecting_reader_arch_loc-d39536e8432","topics":[]},{"title":"Connecting reader cluster to archival location using owner cluster","shortdesc":"<p class=\"shortdesc\">Connect a Rubrik cluster to an archival location when the owner cluster is         available.<\/p>","href":"archival\/arch_connecting_reader_owner_loc.html","attributes":{"data-id":"arch_connecting_reader_owner_loc"},"menu":{"hasChildren":false},"tocID":"arch_connecting_reader_owner_loc-d39536e8443","topics":[]},{"title":"Switching access types in Azure archival location settings","shortdesc":"<p class=\"shortdesc\">You can switch the access type to either Service Principal Based or Access Key Based         by editing the Azure archival location settings. The specified access type authenticates the             <span class=\"ph\">Rubrik Security Cloud<\/span> account for accessing the Azure storage account when creating         an archival location.<\/p>","href":"archival\/switching_access_types_azr_arch_loc_settings.html","attributes":{"data-id":"switching_access_types_azr_arch_loc_settings"},"menu":{"hasChildren":false},"tocID":"switching_access_types_azr_arch_loc_settings-d39536e8454","topics":[]},{"title":"Editing a service principal-based Azure cloud account","shortdesc":"<p class=\"shortdesc\">You can edit an Azure cloud account without OAuth, configured with the service         principal-based authentication method to update the client secret key for snapshot archival         operations.<\/p>","href":"archival\/edit_azr_svc_principal_cloud_acct.html","attributes":{"data-id":"edit_azr_svc_principal_cloud_acct"},"menu":{"hasChildren":false},"tocID":"edit_azr_svc_principal_cloud_acct-d39536e8468","topics":[]},{"title":"Deleting a service principal-based Azure cloud account","shortdesc":"<p class=\"shortdesc\">You can delete an Azure cloud account configured with the service principal-based         authentication method for snapshot archival operations if you do not want <span class=\"ph\">RSC<\/span> to access the Azure subscription specified in the cloud         account.<\/p>","href":"archival\/deleting_service_principal_based_azr_cloud_account.html","attributes":{"data-id":"deleting_service_principal_based_azr_cloud_account"},"menu":{"hasChildren":false},"tocID":"deleting_service_principal_based_azr_cloud_account-d39536e8479","topics":[]},{"title":"Updating Azure cloud account permissions for lifecycle policy detection","shortdesc":"<p class=\"shortdesc\">If an Azure cloud account does not have the permissions required for lifecycle policy         detection, update the account to grant <span class=\"ph\">RSC<\/span> access to scan the account for         harmful lifecycle policies.<\/p>","href":"archival\/updating_azure_account_permissions_lifecycle_policy.html","attributes":{"data-id":"updating_azure_account_permissions_lifecycle_policy"},"menu":{"hasChildren":false},"tocID":"updating_azure_account_permissions_lifecycle_policy-d39536e8493","topics":[]}]}};